const fs = require('node:fs');
const ts = require('typescript');
const Module = require('node:module');
const source = fs.readFileSync('src/content/local-data.ts', 'utf8');
const dataModule = new Module('local-content-check');
dataModule._compile(ts.transpileModule(source, { compilerOptions: { module: ts.ModuleKind.CommonJS } }).outputText, 'local-content-check.js');
const data = dataModule.exports;
const origin = process.argv[2] ?? 'http://localhost:3000';
const routes = ['/', '/giai-phap-nganh-thuc-pham', '/ve-tnt', '/dich-vu', '/dich-vu/erp', '/dich-vu/outsourcing', '/dich-vu/body-shop', '/du-an', '/kien-thuc', '/kien-thuc/blog', '/kien-thuc/guides', '/kien-thuc/faq',
  ...data.projects.map(p => '/du-an/' + p.slug),
  ...data.articles.map(p => '/kien-thuc/blog/' + p.slug)];
function text(html) {
  return html.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '').replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, '').replace(/<!--.*?-->/g, '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}
async function main() {
  const results = [];
  for (const route of [...new Set(routes)]) {
    const versions = [];
    for (const locale of ['vi', 'en']) {
      const response = await fetch(origin + route, { headers: { cookie: 'tnt-locale=' + locale } });
      const html = await response.text();
      const visible = text(html);
      const untranslated = locale === 'en' ? visible.split(/(?<=[.!?])\s+|(?= [A-Z])/).filter(s => /[À-ỹĐđ]/.test(s)) : [];
      const h1 = text(html.match(/<h1[^>]*>[\s\S]*?<\/h1>/)?.[0] ?? '');
      versions.push({ locale, status: response.status, h1, correctLanguage: html.includes('lang="' + locale + '"'), navigation: html.includes('language-switcher'), length: visible.length, untranslated });
      fs.mkdirSync('tmp/route-checks', { recursive: true });
      fs.writeFileSync('tmp/route-checks/' + (route === '/' ? 'home' : route.slice(1).replaceAll('/', '_')) + '-' + locale + '.txt', visible);
    }
    const result = { route, versions };
    results.push(result);
    console.log(route, versions.map(v => v.locale + ':' + v.status + ':' + v.untranslated.length).join(' '));
  }
  fs.writeFileSync('tmp/localization-audit.json', JSON.stringify(results, null, 2));
  const failures = results.filter(r => r.versions.some(v => v.status !== 200 || !v.correctLanguage || !v.navigation || !v.h1 || v.length < 300 || v.untranslated.length));
  console.log('Routes checked:', results.length, 'failures:', failures.map(f => f.route));
  console.log('Untranslated fragments:', results.flatMap(r => r.versions.flatMap(v => v.untranslated.map(s => ({ route:r.route, text:s })))).slice(0, 45));
  if (failures.length) process.exitCode = 1;
}
main().catch(error => { console.error(error); process.exitCode = 1; });

const fs=require('node:fs');
const path=require('node:path');
const crypto=require('node:crypto');
const assert=require('node:assert/strict');
const sharp=require('sharp');
const origin=process.argv[2]??'http://localhost:3000';
const audit=JSON.parse(fs.readFileSync('tmp/localization-audit.json','utf8'));
const attr=(tag,name)=>tag.match(new RegExp(name+'="([^"]*)"'))?.[1]?.replaceAll('&amp;','&');

async function main(){
  const contentHash=crypto.createHash('sha256').update(fs.readFileSync('src/content/local-data.ts')).digest('hex');
  assert.equal(contentHash,fs.readFileSync('tmp/content-before-wireframe.sha256','utf8'),'Original content must remain unchanged');
  const links=new Set(),images=new Set(),failures=[];
  let photoElements=0;
  for(const {route}of audit){
    const response=await fetch(origin+route);
    assert.equal(response.status,200,route);
    const html=(await response.text()).replace(/<script\b[^>]*>[\s\S]*?<\/script>/g,'');
    if(!['/','/ve-tnt','/giai-phap-nganh-thuc-pham'].includes(route))assert.ok(html.includes('wf-page'),'Wireframe layout missing: '+route);
    for(const m of html.matchAll(/<img\b[^>]*>/g)){
      const tag=m[0];
      assert.ok(attr(tag,'class')?.includes('tnt-media'),'Unmanaged image: '+route);
      const kind=attr(tag,'data-media-kind');
      assert.ok(['photo','cutout','background'].includes(kind),'Missing image role: '+route);
      if(kind==='photo')photoElements++;
      const url=new URL(attr(tag,'src'),origin);
      const src=url.pathname==='/_next/image'?url.searchParams.get('url'):url.pathname;
      if(src?.startsWith('/images/'))images.add(src);
    }
    for(const m of html.matchAll(/<a\b[^>]*>/g)){
      const href=attr(m[0],'href');
      if(href?.startsWith('/')&&!href.startsWith('/_next/'))links.add(href.split('#')[0]);
    }
  }
  for(const src of images){
    const file=path.join('public',src.slice(1));
    assert.ok(fs.existsSync(file),'Missing image '+src);
    const m=await sharp(file).metadata();
    if(src.includes('/collection/')){assert.equal(m.width,1600);assert.equal(m.height,1000);}
  }
  for(const href of links){const r=await fetch(origin+href);if(r.status!==200)failures.push([href,r.status]);}
  const collection=fs.readdirSync('public/images/collection').filter(f=>f.endsWith('.webp'));
  assert.equal(collection.length,9);
  const result={routes:audit.length,photoElements,uniqueImages:images.size,generatedImages:collection.length,internalDestinations:links.size,failures,originalContentUnchanged:true};
  fs.writeFileSync('tmp/wireframe-audit.json',JSON.stringify(result,null,2));
  console.log(result);
  assert.equal(failures.length,0);
}
main().catch(error=>{console.error(error);process.exitCode=1});

const ts = require('typescript');
const fs = require('node:fs');
const path = require('node:path');
const items = new Set();
function walk(dir) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const file = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(file);
    else if (/\.tsx?$/.test(file) && !file.includes(`${path.sep}i18n${path.sep}`)) {
      const source = ts.createSourceFile(file, fs.readFileSync(file, 'utf8'), ts.ScriptTarget.Latest, true, file.endsWith('tsx') ? ts.ScriptKind.TSX : ts.ScriptKind.TS);
      function visit(node) {
        if (ts.isStringLiteral(node) || ts.isNoSubstitutionTemplateLiteral(node) || ts.isJsxText(node)) {
          const value = node.text.replace(/\s+/g, ' ').trim();
          if (/[À-ỹĐđ]/.test(value) && !value.startsWith('/') && !value.includes('http')) items.add(value);
        }
        ts.forEachChild(node, visit);
      }
      visit(source);
    }
  }
}
walk('src');
const values = [...items].sort();
fs.mkdirSync('tmp', { recursive: true });
fs.writeFileSync('tmp/translation-source.json', JSON.stringify(values, null, 2));
console.log(values.length + ' translation strings');
for (let i = 0; i < values.length; i++) console.log(i + '\t' + values[i]);

const sharp = require('sharp');
const fs = require('node:fs/promises');

// Preserve the original tagline outlines; redraw the geometric mark as vectors.
async function main() {
  const { data, info } = await sharp('public/images/reference/tnt-logo.jpg')
    .removeAlpha().raw().toBuffer({ resolveWithObject: true });
  const dark = (x, y) => x >= 195 && x < 1005 && y >= 730 && y < 810 &&
    data[(y * info.width + x) * info.channels] < 100;
  const edges = new Map();
  function edge(x, y, nx, ny) {
    const key = `${x},${y}`;
    if (!edges.has(key)) edges.set(key, []);
    edges.get(key).push([nx, ny]);
  }
  for (let y = 730; y < 810; y++) for (let x = 195; x < 1005; x++) {
    if (!dark(x, y)) continue;
    if (!dark(x, y - 1)) edge(x, y, x + 1, y);
    if (!dark(x + 1, y)) edge(x + 1, y, x + 1, y + 1);
    if (!dark(x, y + 1)) edge(x + 1, y + 1, x, y + 1);
    if (!dark(x - 1, y)) edge(x, y + 1, x, y);
  }
  const paths = [];
  while (edges.size) {
    const first = edges.keys().next().value;
    let key = first;
    const points = [];
    do {
      points.push(key.split(',').map(Number));
      const list = edges.get(key);
      const next = list.pop();
      if (!list.length) edges.delete(key);
      key = next.join(',');
    } while (key !== first && edges.has(key));
    const corners = points.filter((p, i) => {
      const a = points[(i + points.length - 1) % points.length];
      const b = points[(i + 1) % points.length];
      return (p[0] - a[0]) * (b[1] - p[1]) !== (p[1] - a[1]) * (b[0] - p[0]);
    });
    if (corners.length > 2) paths.push('M' + corners.map(p => p.join(' ')).join('L') + 'Z');
  }
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="190 390 820 420"><title>TNT — Software solutions provider</title><g fill="#ed2d34"><path d="M304 400H432L417 482H360Z"/><path d="M763 400H857L806 650L741 516Z"/></g><path fill="#423f92" d="M452 400H666L799 682H709L646 541L618 682H539L577 482H532L491 682H401Z"/><path fill="#111" fill-rule="evenodd" d="${paths.join('')}"/></svg>\n`;
  await fs.writeFile('public/images/tnt-logo.svg', svg);
  await sharp(Buffer.from(svg)).resize(820, 420).png().toFile('tmp/tnt-logo-preview.png');
}
main().catch(error => { console.error(error); process.exitCode = 1; });

const ts = require('typescript');
const fs = require('node:fs');
const path = require('node:path');
const attrs = new Set(['title', 'highlightedTitle', 'description', 'eyebrow', 'label', 'submitLabel', 'alt', 'placeholder', 'aria-label', 'aria-description']);
function jsxText(text) {
  const lines = text.replace(/\t/g, ' ').split(/\r?\n/);
  let last = 0;
  lines.forEach((line, i) => { if (/[^ ]/.test(line)) last = i; });
  return lines.map((line, i) => {
    if (i !== 0) line = line.replace(/^ +/, '');
    if (i !== lines.length - 1) line = line.replace(/ +$/, '');
    return line ? line + (i !== last ? ' ' : '') : '';
  }).join('');
}
const printer = ts.createPrinter({ newLine: ts.NewLineKind.LineFeed });
function walk(dir) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const file = path.join(dir, entry.name);
    if (entry.isDirectory()) { if (!['i18n','ui'].includes(entry.name)) walk(file); continue; }
    if (!file.endsWith('.tsx') || ['layout.tsx','language-switcher.tsx'].includes(entry.name)) continue;
    const original = fs.readFileSync(file, 'utf8');
    if (original.includes('getI18n') || original.includes('useI18n')) continue;
    const source = ts.createSourceFile(file, original, ts.ScriptTarget.Latest, true, ts.ScriptKind.TSX);
    const client = /^['"]use client['"];/.test(original.trimStart());
    let changed = false;
    const transformed = ts.transform(source, [context => {
      const f = context.factory;
      const call = expression => f.createCallExpression(f.createIdentifier('t'), undefined, [expression]);
      function visit(node) {
        if (ts.isJsxText(node)) {
          const text = jsxText(node.text);
          if (!text.trim()) return node;
          return f.createJsxExpression(undefined, call(f.createStringLiteral(text)));
        }
        if (ts.isJsxExpression(node) && node.expression && !ts.isJsxAttribute(node.parent)) {
          return f.updateJsxExpression(node, call(ts.visitNode(node.expression, visit)));
        }
        if (ts.isJsxAttribute(node) && attrs.has(node.name.getText(source)) && node.initializer) {
          const init = node.initializer;
          if (ts.isStringLiteral(init)) return f.updateJsxAttribute(node, node.name, f.createJsxExpression(undefined, call(f.createStringLiteral(init.text))));
          if (ts.isJsxExpression(init) && init.expression) return f.updateJsxAttribute(node, node.name, f.createJsxExpression(undefined, call(ts.visitNode(init.expression, visit))));
        }
        if (ts.isFunctionDeclaration(node) && node.name && /^[A-Z]/.test(node.name.text) && node.body) {
          const updated = ts.visitEachChild(node, visit, context);
          let usesT = false;
          function find(child) {
            if (ts.isCallExpression(child) && ts.isIdentifier(child.expression) && child.expression.text === 't') usesT = true;
            ts.forEachChild(child, find);
          }
          find(updated.body);
          if (!usesT) return updated;
          changed = true;
          const binding = f.createVariableStatement(undefined, f.createVariableDeclarationList([
            f.createVariableDeclaration(f.createObjectBindingPattern([f.createBindingElement(undefined, undefined, 't')]), undefined, undefined,
              client ? f.createCallExpression(f.createIdentifier('useI18n'), undefined, []) : f.createAwaitExpression(f.createCallExpression(f.createIdentifier('getI18n'), undefined, [])))
          ], ts.NodeFlags.Const));
          const modifiers = [...(updated.modifiers ?? [])];
          if (!client && !modifiers.some(m => m.kind === ts.SyntaxKind.AsyncKeyword)) modifiers.push(f.createModifier(ts.SyntaxKind.AsyncKeyword));
          return f.updateFunctionDeclaration(updated, modifiers, updated.asteriskToken, updated.name, updated.typeParameters, updated.parameters, updated.type, f.updateBlock(updated.body, [binding, ...updated.body.statements]));
        }
        return ts.visitEachChild(node, visit, context);
      }
      return node => ts.visitNode(node, visit);
    }]);
    if (changed) {
      const name = client ? 'useI18n' : 'getI18n';
      const specifier = client ? '@/i18n/provider' : '@/i18n/server';
      let printed = printer.printFile(transformed.transformed[0]);
      const line = `import { ${name} } from "${specifier}";\n`;
      printed = client ? printed.replace(/(["']use client["'];\n)/, '$1' + line) : line + printed;
      printed = printed.replace(/\\u([0-9a-fA-F]{4})/g, (_, code) => String.fromCharCode(parseInt(code, 16)));
      fs.writeFileSync(file, printed);
      console.log(file);
    }
    transformed.dispose();
  }
}
walk('src/app'); walk('src/components');

const fs=require('node:fs');
const sharp=require('sharp');
const sources=require('../tmp/new-media-sources.json');
async function main(){
  fs.mkdirSync('public/images/collection',{recursive:true});
  for(const [name,file] of Object.entries(sources)){
    if(!file)throw new Error('Missing generated image '+name);
    const dest='public/images/collection/'+name+'.webp';
    await sharp(file).resize(1600,1000,{fit:'cover',position:'centre'}).webp({quality:94,effort:4}).toFile(dest);
    const m=await sharp(dest).metadata();
    console.log(name,m.width+'x'+m.height,fs.statSync(dest).size+' bytes');
  }
}
main().catch(e=>{console.error(e);process.exitCode=1});

const fs = require('fs');
(async () => {
  const manifest = JSON.parse(fs.readFileSync('.next/server/server-reference-manifest.json', 'utf8'));
  const entry = Object.entries(manifest.node).find(([,v]) => v.exportedName === 'changeLanguage');
  if (!entry) throw Error('Missing language action');
  for (const locale of ['en', 'vi']) {
    const response = await fetch('http://localhost:3001/dich-vu', {method:'POST', headers:{'Next-Action':entry[0], Origin:'http://localhost:3001', 'Content-Type':'text/plain;charset=UTF-8'}, body:JSON.stringify([locale])});
    const cookie = response.headers.get('set-cookie');
    if (!response.ok || !cookie?.includes('tnt-locale='+locale)) throw Error('Language action failed '+locale);
    for (const route of ['/du-an','/kien-thuc']) {
      const html = await (await fetch('http://localhost:3001'+route, {headers:{Cookie:cookie.split(';')[0]}})).text();
      if (!html.includes('lang="'+locale+'"')) throw Error('Language not preserved '+route);
    }
  }
  console.log('VI/EN action and cross-page persistence passed');
})().catch(e=>{console.error(e.message);process.exitCode=1});

const fs=require('fs'), path=require('path'), cp=require('child_process');
const found=new Map();
function walk(d){for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);if(e.isDirectory())walk(p);else if(p.endsWith('.map')){try{const j=JSON.parse(fs.readFileSync(p,'utf8'));function scan(m){if(m.sections)m.sections.forEach(s=>scan(s.map));(m.sources||[]).forEach((s,i)=>{if(s.includes('/TNT_website_project/src/')&&m.sourcesContent?.[i]){const f=decodeURIComponent(s.split('/TNT_website_project/')[1]);const content=m.sourcesContent[i];if(!content.includes('getI18n')&&!content.includes('useI18n'))found.set(f,content);}})}scan(j)}catch{}}}}
walk('.next/dev');
console.log('Available source snapshots:',[...found.keys()].filter(s=>s.endsWith('.tsx')));
const files=[];
function targets(d){for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);if(e.isDirectory())targets(p);else if(p.endsWith('.tsx')&&!p.includes('i18n')&&fs.readFileSync(p,'utf8').includes('const { t }'))files.push(p.replaceAll('\\','/'));}}
targets('src');
for(const file of files){let original=found.get(file);if(!original){try{original=cp.execFileSync('git',['show','HEAD:'+file],{encoding:'utf8',stdio:['ignore','pipe','ignore']});}catch{console.log('MISSING',file);continue;}}const out=path.join('tmp/before-localization',file);fs.mkdirSync(path.dirname(out),{recursive:true});fs.writeFileSync(out,original);console.log('Saved',file);}
